#!/usr/bin/env python3
# 重建内置样例 examples/sample_room.dxf（SkillHub 轻量包不收录 .dxf，由内嵌 base64 现场还原）。
# 用法: python3 generate_sample.py <输出路径>
import base64, pathlib, sys

DATA = ''

def main():
    import pyboot
    pyboot.ensure_utf8_io()
    if len(sys.argv) < 2:
        print("usage: generate_sample.py <outpath>", file=sys.stderr)
        return 1
    out = pathlib.Path(sys.argv[1])
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_bytes(base64.b64decode(DATA))
    print(f"generated {out} ({out.stat().st_size} bytes)")
    return 0

if __name__ == '__main__':
    sys.exit(main())
